import {useState} from 'react';
import {Activity,AlertTriangle,ArrowRight,ArrowUpRight,Bell,CalendarDays,CheckCircle2,ChevronRight,CircleDot,ClipboardCheck,ClipboardList,Clock3,FileClock,Plus,RefreshCw,Sparkles,Target,UsersRound} from 'lucide-react';
import {buildDashboardIntelligence} from '../../lib/externalDashboardIntelligence';
import {Button,FeedbackState,FilterBar,LoadingSkeleton,PageHeader,StatusChip,Surface} from './ui/ExternalUI';

const KPI=[['Active clients','activeClients',UsersRound,'clients','clients','People currently active in your practice','blue'],['Onboarding completed','onboardingCompleted',CheckCircle2,'clients','onboarding','Clients with completed intake','emerald'],['Follow-ups due today','followupsDueToday',FileClock,'followups','followups','Actions due before day end','amber'],['Clients needing review','clientsNeedingReview',AlertTriangle,'attention','attention','Open operational signals','rose'],['New this month','newClientsThisMonth',ArrowUpRight,'clients','clients','Recently added clients','slate'],['Consultations this week','consultationsThisWeek',CalendarDays,'consultations','consultations','Scheduled this week','slate'],['Overdue follow-ups','overdueFollowups',Clock3,'followups','followups','Past their due date','slate'],['Overdue tasks','overdueTasks',ClipboardList,'tasks','tasks','Open past due tasks','slate']];
const TONES={blue:'border-blue-200 bg-blue-50 text-blue-700',emerald:'border-emerald-200 bg-emerald-50 text-emerald-700',amber:'border-amber-200 bg-amber-50 text-amber-700',rose:'border-rose-200 bg-rose-50 text-rose-700',slate:'border-slate-200 bg-slate-50 text-slate-600'};
const SEVERITY={P1_CRITICAL:{tone:'critical',label:'P1 Critical',accent:'border-l-red-600',icon:'bg-red-50 text-red-700'},P2_HIGH:{tone:'dangerTone',label:'P2 High',accent:'border-l-orange-500',icon:'bg-orange-50 text-orange-700'},P3_MEDIUM:{tone:'warning',label:'P3 Medium',accent:'border-l-amber-500',icon:'bg-amber-50 text-amber-700'},P4_LOW:{tone:'info',label:'P4 Low',accent:'border-l-slate-400',icon:'bg-slate-100 text-slate-600'}};
const FILTERS=['All','Critical','High','Medium','Low','Overdue','Onboarding','Follow-ups','Tasks','Goals'];

function KpiCard({label,value,Icon,unavailable,onClick,support,tone,primary}){return <button onClick={onClick} className={`group relative min-h-[126px] overflow-hidden rounded-2xl border bg-white p-4 text-left transition duration-200 hover:-translate-y-0.5 hover:border-slate-300 hover:shadow-[0_12px_30px_rgba(15,23,42,.08)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-600 focus-visible:ring-offset-2 ${primary?'border-slate-200 shadow-[0_2px_8px_rgba(15,23,42,.05)]':'border-slate-200/80'}`}><span className={`flex h-9 w-9 items-center justify-center rounded-xl border ${TONES[tone]}`}><Icon aria-hidden="true" size={17}/></span><span className="mt-4 flex items-end justify-between gap-2"><span><span className="block text-xs font-semibold uppercase tracking-[.08em] text-slate-500">{label}</span><strong className="mt-1.5 block text-[2rem] font-semibold leading-none tracking-[-.05em] text-slate-950">{unavailable?'—':value}</strong></span><ChevronRight aria-hidden="true" size={16} className="mb-1 text-slate-300 transition group-hover:translate-x-0.5 group-hover:text-blue-700"/></span><span className={`mt-2 block text-[11px] leading-4 ${unavailable?'font-medium text-amber-700':'text-slate-500'}`}>{unavailable?'Source unavailable':support}</span></button>}
function CompactMetric({label,value,Icon,unavailable,onClick}){return <button onClick={onClick} className="flex min-h-16 items-center gap-3 rounded-2xl border border-white/70 bg-white/70 px-3 text-left shadow-sm transition hover:bg-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-600"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-slate-100 text-slate-600"><Icon size={16}/></span><span className="min-w-0"><strong className="block text-xl font-semibold leading-none tracking-[-.04em] text-slate-950">{unavailable?'—':value}</strong><span className="mt-1 block truncate text-[11px] font-medium text-slate-500">{unavailable?'Source unavailable':label}</span></span></button>}

const CHART_COLOURS=['bg-blue-600','bg-emerald-600','bg-amber-500','bg-slate-400'];
function Distribution({title,question,data,unavailable,Icon}){const entries=Object.entries(data).filter(([,value])=>value>0);const total=entries.reduce((sum,[,value])=>sum+value,0);return <Surface density="standard" className="h-full border-slate-200 shadow-[0_2px_12px_rgba(15,23,42,.04)]"><div className="flex items-start justify-between gap-4"><div className="flex gap-3"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border border-blue-100 bg-blue-50 text-blue-700"><Icon aria-hidden="true" size={18}/></span><div><h3 className="text-base font-semibold text-slate-950">{title}</h3><p className="mt-0.5 text-xs text-slate-500">{question}</p></div></div>{!unavailable&&<div className="text-right"><strong className="block text-2xl font-semibold tracking-[-.04em] text-slate-950">{total}</strong><span className="text-[11px] text-slate-500">total</span></div>}</div>{unavailable?<FeedbackState kind="error" title={`${title} unavailable`} copy="The source request failed. No zero or empty result is inferred."/>:total?<><div aria-label={`${title} distribution`} className="mt-6 flex h-3 gap-0.5 overflow-hidden rounded-full bg-slate-100 p-0.5">{entries.map(([label,value],index)=><span key={label} title={`${label}: ${value}`} style={{width:`${value/total*100}%`}} className={`rounded-full ${CHART_COLOURS[index%CHART_COLOURS.length]}`}/>)}</div><dl className="mt-5 grid grid-cols-2 gap-x-5 gap-y-3">{entries.map(([label,value],index)=><div key={label} className="flex items-center justify-between gap-3 border-b border-slate-100 pb-2 text-xs"><dt className="flex min-w-0 items-center gap-2 text-slate-600"><span className={`h-2.5 w-2.5 shrink-0 rounded-full ${CHART_COLOURS[index%CHART_COLOURS.length]}`}/><span className="truncate capitalize">{label.replaceAll('_',' ').toLowerCase()}</span></dt><dd className="font-semibold text-slate-950">{value}</dd></div>)}</dl></>:<FeedbackState title="No confirmed data" copy="There are no source records in this distribution yet."/>}</Surface>}

function matchesFilter(item,filter){if(filter==='All')return true;if(filter==='Critical')return item.level==='P1_CRITICAL';if(filter==='High')return item.level==='P2_HIGH';if(filter==='Medium')return item.level==='P3_MEDIUM';if(filter==='Low')return item.level==='P4_LOW';if(filter==='Overdue')return item.signal.includes('OVERDUE');return item.signal.startsWith(filter.toUpperCase().replace('-','_').replace('FOLLOW_UPS','FOLLOW_UP'))}

function PriorityInbox({items,onNavigate,onOpen}){const [filter,setFilter]=useState('All');const visible=items.filter(item=>matchesFilter(item,filter));return <section id="needs-attention" className="min-w-0 overflow-hidden border-slate-300 flex h-full flex-col rounded-[26px] bg-slate-950 p-5 text-white shadow-[0_24px_55px_-32px_rgba(15,23,42,.9)] sm:p-6"><div className="flex items-start justify-between gap-3"><div><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-white/10 text-amber-300"><Bell aria-hidden="true" size={19}/></span><h3 className="mt-5 text-xl font-semibold tracking-[-.03em]">Needs attention</h3><p className="mt-1 text-xs text-slate-400">Your prioritised operational work queue</p></div><span className="text-right"><strong className="block text-4xl font-semibold tracking-[-.06em]">{items.length}</strong><span className="text-[11px] text-slate-400">active</span></span></div><FilterBar label="Priority filters"><div className="mt-5 flex gap-1.5 overflow-x-auto pb-1">{FILTERS.slice(0,5).map(item=><button key={item} onClick={()=>setFilter(item)} aria-pressed={filter===item} className={`min-h-11 shrink-0 rounded-xl px-3 text-xs font-semibold ${filter===item?'bg-white text-slate-950':'bg-white/10 text-slate-300 hover:bg-white/15'}`}>{item}</button>)}</div></FilterBar><div className="mt-3 divide-y divide-white/10">{visible.slice(0,3).map(item=>{const severity=SEVERITY[item.level]||SEVERITY.P4_LOW;return <button key={item.key} onClick={()=>item.target==='client'&&item.client?onOpen(item.client):onNavigate(item.target)} className="group flex min-h-[92px] w-full items-center justify-between gap-3 py-4 text-left"><div className="min-w-0"><div className="flex items-center gap-2"><span className="text-[10px] font-bold uppercase tracking-[.12em] text-amber-300">{severity.label}</span><span className="truncate text-[10px] uppercase tracking-[.08em] text-slate-500">{item.signal.replaceAll('_',' ')}</span></div><strong className="mt-2 block truncate text-sm">{item.client?.displayName||'Practice task'}</strong><p className="mt-1 line-clamp-1 text-xs text-slate-400">{item.reason}</p></div><ChevronRight size={17} className="shrink-0 text-slate-500 transition group-hover:translate-x-0.5 group-hover:text-white"/></button>})}</div>{!visible.length&&<p className="mt-6 rounded-2xl bg-white/10 p-4 text-sm text-slate-300">{items.length?'No priorities match this filter.':'No confirmed priorities in loaded source records.'}</p>}<button onClick={()=>onNavigate('clients')} className="mt-auto min-h-11 self-start text-xs font-semibold text-amber-300">Open client workspace <ArrowRight className="ml-1 inline" size={14}/></button></section>}

function Agenda({items,onNavigate}){return <Surface density="standard" className="h-full border-slate-200 shadow-[0_2px_12px_rgba(15,23,42,.04)]"><div className="flex items-start justify-between gap-3"><div className="flex gap-3"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border border-violet-100 bg-violet-50 text-violet-700"><CalendarDays aria-hidden="true" size={18}/></span><div><h3 className="text-base font-semibold text-slate-950">Today</h3><p className="mt-0.5 text-xs text-slate-500">Your agenda and next events</p></div></div><Button variant="ghost" onClick={()=>onNavigate('calendar')}>Calendar <ArrowRight size={14}/></Button></div>{items.length?<div className="relative mt-5 space-y-1 before:absolute before:bottom-4 before:left-[3.15rem] before:top-4 before:w-px before:bg-slate-200">{items.map((item,index)=><article key={item.id} className="relative grid grid-cols-[2.5rem_1fr] gap-5 rounded-xl px-1 py-3 transition hover:bg-slate-50"><time className="text-right text-[11px] font-semibold text-violet-700">{new Date(item.due_at).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})}</time><span className="absolute left-[2.9rem] top-[1.05rem] z-10 flex h-2.5 w-2.5 rounded-full border-2 border-white bg-violet-500 ring-1 ring-violet-200"/><div className="min-w-0"><p className="truncate text-sm font-semibold text-slate-900">{item.title}</p><div className="mt-1.5 flex flex-wrap items-center gap-2"><span className="text-xs text-slate-500">{new Date(item.due_at).toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'})}</span><StatusChip tone={index===0?'info':'neutral'}>{item.status?.replaceAll('_',' ')||'Scheduled'}</StatusChip></div></div></article>)}</div>:<FeedbackState title="A clear schedule" copy="No upcoming consultations are confirmed in the loaded period."/>}</Surface>}

function RecentActivity({items}){return <Surface density="standard" className="border-slate-200 shadow-[0_2px_12px_rgba(15,23,42,.04)]"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="text-base font-semibold text-slate-950">Recent activity</h3><p className="mt-1 text-xs text-slate-500">A factual feed of confirmed practice events.</p></div><span className="flex items-center gap-1.5 text-xs font-medium text-slate-500"><Activity size={14}/>Live practice feed</span></div>{items.length?<ol className="mt-5 grid gap-0 md:grid-cols-2 xl:grid-cols-3">{items.map((item,index)=><li key={item.id} className={`group flex min-w-0 gap-3 border-slate-100 py-4 md:px-4 ${index?'border-t md:border-t-0 md:border-l':''}`}><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl border border-emerald-100 bg-emerald-50 text-emerald-700"><ClipboardCheck aria-hidden="true" size={16}/></span><div className="min-w-0"><p className="truncate text-sm font-semibold text-slate-900">{item.title}</p><time className="mt-1 block text-xs text-slate-500">{new Date(item.created_at).toLocaleString()}</time></div></li>)}</ol>:<FeedbackState title="No recent activity" copy="No notification activity is confirmed for this period."/>}</Surface>}

function FeaturedPriority({item,onNavigate,onOpen}){if(!item)return <section className="flex min-h-[290px] flex-col justify-between rounded-[26px] border border-slate-200 bg-white p-5 shadow-sm"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-slate-400">Featured focus</p><h3 className="mt-4 text-xl font-semibold">Your priority queue is clear</h3><p className="mt-2 text-sm leading-6 text-slate-500">No actionable priority is confirmed in loaded source records.</p></div><CheckCircle2 className="text-emerald-600" size={28}/></section>;const severity=SEVERITY[item.level]||SEVERITY.P4_LOW;return <section className="flex min-h-[290px] flex-col overflow-hidden rounded-[26px] border border-amber-200 bg-[#fff8df] p-5 shadow-sm"><div className="flex items-center justify-between"><p className="text-[11px] font-bold uppercase tracking-[.16em] text-amber-800">Featured focus</p><StatusChip tone={severity.tone}>{severity.label}</StatusChip></div><div className="mt-7"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-white font-semibold text-amber-800 shadow-sm">{(item.client?.displayName||'P').split(/\s+/).map(part=>part[0]).join('').slice(0,2)}</span><h3 className="mt-5 truncate text-2xl font-semibold tracking-[-.04em]">{item.client?.displayName||'Practice task'}</h3><p className="mt-2 text-sm leading-6 text-slate-700">{item.reason}</p>{item.completionPercent!=null&&<div className="mt-5"><div className="flex justify-between text-xs font-semibold"><span>Onboarding progress</span><span>{item.completionPercent}%</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-amber-200"><span className="block h-full rounded-full bg-amber-500" style={{width:`${item.completionPercent}%`}}/></div></div>}</div><button onClick={()=>item.target==='client'&&item.client?onOpen(item.client):onNavigate(item.target)} className="mt-auto inline-flex min-h-11 items-center self-start text-sm font-semibold text-slate-950">{item.action}<ArrowUpRight className="ml-2" size={16}/></button></section>}
function OnboardingProgress({clients,complete,available}){const total=clients.length;const pct=available&&total?Math.round(complete/total*100):null;return <section className="flex min-h-[290px] flex-col rounded-[26px] border border-slate-200 bg-white p-5 shadow-sm"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-blue-700">Practice progress</p><h3 className="mt-2 text-lg font-semibold">Onboarding momentum</h3></div>{pct==null?<p className="mt-6 rounded-2xl bg-amber-50 p-4 text-sm text-amber-900">Onboarding source unavailable. No completion rate is inferred.</p>:<><div className="mt-7 flex items-end justify-between"><strong className="text-5xl font-semibold tracking-[-.07em]">{pct}%</strong><span className="text-right text-xs leading-5 text-slate-500">{complete} complete<br/>{total-complete} in progress</span></div><div className="mt-5 flex h-4 gap-1 overflow-hidden rounded-full bg-slate-100 p-1"><span className="rounded-full bg-emerald-500" style={{width:`${pct}%`}}/><span className="flex-1 rounded-full bg-amber-300"/></div><div className="mt-5 grid grid-cols-7 items-end gap-1" aria-label="Onboarding visual summary">{clients.slice(0,7).map((client,index)=>{const value=client.intakeState==='COMPLETED'?100:Number(client.intakeCompletionPercent)||0;return <span key={client.id} className="rounded-t bg-blue-100" style={{height:`${Math.max(12,value*.58)}px`,backgroundColor:index===0?'#2563eb':undefined}} title={`${client.displayName}: ${value}%`}/>})}</div></>}</section>}
function PracticeSnapshot({model,unavailable}){const rows=[['Onboarding',unavailable.onboarding?'Unavailable':`${model.kpis.onboardingCompleted} complete`],['Follow-ups',unavailable.followups?'Unavailable':`${model.kpis.followupsDueToday} due · ${model.kpis.overdueFollowups} overdue`],['Goals',unavailable.goals?'Unavailable':`${Object.values(model.charts.goals).reduce((sum,value)=>sum+value,0)} tracked`],['Tasks',unavailable.tasks?'Unavailable':`${model.kpis.overdueTasks} overdue`]];return <section className="rounded-[26px] border border-slate-200 bg-[#eef4f3] p-5 shadow-sm"><p className="text-[11px] font-bold uppercase tracking-[.16em] text-teal-800">Practice snapshot</p><h3 className="mt-2 text-lg font-semibold">Operational picture</h3><dl className="mt-5 divide-y divide-slate-200/80">{rows.map(([label,value])=><div key={label} className="flex items-center justify-between gap-4 py-3"><dt className="text-sm font-medium text-slate-700">{label}</dt><dd className={`text-xs font-semibold ${value==='Unavailable'?'text-amber-800':'text-slate-950'}`}>{value}</dd></div>)}</dl></section>}

function DashboardLoading(){return <div aria-label="Loading dashboard intelligence" className="space-y-5"><LoadingSkeleton height="8rem"/><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{Array.from({length:8},(_,i)=><LoadingSkeleton key={i} height="8rem" label="Loading KPI"/>)}</div><div className="grid gap-5 lg:grid-cols-12"><div className="lg:col-span-8"><LoadingSkeleton height="26rem" label="Loading priority inbox"/></div><div className="lg:col-span-4"><LoadingSkeleton height="26rem" label="Loading agenda"/></div></div></div>}

export function ExternalIntelligentHome({clients,user,data,state,error,onRetry,onAdd,onNavigate,onOpen}){if(state==='loading')return <DashboardLoading/>;if(state==='error')return <Surface><FeedbackState kind="error" title="Dashboard intelligence unavailable" copy={`${error}. Client records are not presented as empty.`} action={<Button icon={RefreshCw} onClick={onRetry}>Retry</Button>}/></Surface>;
  const model=buildDashboardIntelligence({clients,resources:data.resources,notifications:data.notifications});
  const greeting=new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening';
  const primaryKpis=KPI.filter(([,key])=>['activeClients','onboardingCompleted','clientsNeedingReview'].includes(key));
  const secondaryKpis=KPI.filter(([,key])=>['followupsDueToday','consultationsThisWeek','overdueTasks','newClientsThisMonth'].includes(key));
  const sourceUnavailable=source=>data.unavailable?.includes(source)||(source==='onboarding'&&!model.availability.onboarding)||(source==='attention'&&data.unavailable?.some(item=>['followups','tasks','goals','notifications'].includes(item)));
  return <div className="rounded-[32px] border border-white/80 bg-[#ecebe6] p-3 pb-24 shadow-[0_30px_80px_-60px_rgba(15,23,42,.55)] sm:p-5 lg:pb-5"><div className="grid gap-4 lg:grid-cols-12"><header className="rounded-[26px] bg-[#f9f8f4] p-5 sm:p-7 lg:col-span-7"><p className="text-[11px] font-bold uppercase tracking-[.16em] text-blue-700">Practice pulse · Practice overview</p><p className="mt-3 text-xs font-semibold text-slate-500">{new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</p><h1 className="mt-4 text-3xl font-semibold tracking-[-.05em] text-slate-950 sm:text-4xl">{greeting}, {(user?.name||'Consultant').split(' ')[0]}</h1><p className="mt-3 text-sm text-slate-600">{model.kpis.activeClients} active clients · {model.items.length} priorities need attention</p><div className="mt-7 flex flex-wrap gap-2"><Button variant="primary" icon={Plus} onClick={onAdd}>Add client</Button><Button onClick={()=>onNavigate('consultations')}>Schedule</Button></div><div className="mt-6 flex flex-wrap gap-4 text-[11px] text-slate-500"><span className="flex items-center gap-1.5"><Sparkles size={14} className="text-blue-600"/>Intelligent practice</span><span className="flex items-center gap-1.5"><CircleDot size={14} className="text-emerald-600"/>Live operational truth</span></div></header><section aria-label="Primary practice metrics" className="grid gap-3 sm:grid-cols-3 lg:col-span-5 lg:grid-cols-2">{primaryKpis.map(([label,key,Icon,target,source,support,tone],index)=><div key={key} className={index===0?'sm:col-span-1 lg:col-span-2':''}><KpiCard label={label} value={model.kpis[key]} Icon={Icon} support={support} tone={tone} primary unavailable={sourceUnavailable(source)} onClick={()=>target==='attention'?document.getElementById('needs-attention')?.scrollIntoView({behavior:'smooth'}):onNavigate(target)}/></div>)}</section></div>
    {error&&<div role="status" className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-950"><AlertTriangle aria-hidden="true" className="mt-0.5 shrink-0 text-amber-700" size={17}/><span><strong>Partial dashboard.</strong> {error}. Unavailable metrics are not shown as zero.</span></div>}
    <section aria-label="Secondary practice metrics" className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">{secondaryKpis.map(([label,key,Icon,target,source])=><CompactMetric key={key} label={label} value={model.kpis[key]} Icon={Icon} unavailable={sourceUnavailable(source)} onClick={()=>onNavigate(target)}/>)}</section>
    <div className="mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-12"><div className="xl:col-span-4"><FeaturedPriority item={model.items[0]} onNavigate={onNavigate} onOpen={onOpen}/></div><div className="xl:col-span-4"><OnboardingProgress clients={clients} complete={model.kpis.onboardingCompleted} available={model.availability.onboarding}/></div><div className="md:col-span-2 xl:col-span-4"><PriorityInbox items={model.items} onNavigate={onNavigate} onOpen={onOpen}/></div></div>
    <div className="mt-4 grid gap-4 lg:grid-cols-12"><div className="lg:col-span-4"><PracticeSnapshot model={model} unavailable={{onboarding:!model.availability.onboarding,followups:data.unavailable?.includes('followups'),goals:data.unavailable?.includes('goals'),tasks:data.unavailable?.includes('tasks')}}/></div><div className="lg:col-span-8"><Agenda items={model.upcoming} onNavigate={onNavigate}/></div></div>
    <section aria-label="Practice analytics" className="mt-4 grid gap-4 lg:grid-cols-12"><h2 className="sr-only">Care momentum</h2><div className="lg:col-span-5"><Distribution title="Follow-up status" question="Are follow-ups being completed?" data={model.charts.followups} unavailable={data.unavailable?.includes('followups')} Icon={Clock3}/></div><div className="lg:col-span-3"><Distribution title="Goal status" question="How are active goals distributed?" data={model.charts.goals} unavailable={data.unavailable?.includes('goals')} Icon={Target}/></div><div className="lg:col-span-4"><RecentActivity items={model.recent}/></div></section>
  </div>;
}
